INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (99, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA member who succeeded Zohran Mamdani, engaged in civil disobedience protesting "genocide in Gaza," participated in pro-Palestine demonstrations, and supports the Not on Our Dime Act.', 'Participated in NYU Gaza Solidarity Encampment holding "PREGNANT MAMA FOR A FREE PALESTINE" sign. Engaged in civil disobedience protesting genocide in Gaza. Described Not on Our Dime Act as addressing "tax-exempt donations to illegal Israeli settlements." Won special election Feb 2026 to succeed Mayor Mamdani with DSA endorsement. Sources: https://socialists.nyc/press-releases/democratic-socialist-diana-moreno-wins-special-election-in-assembly-district-36-to-succeed-mayor-mamdani/ , https://jaco') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA member who succeeded Zohran Mamdani, engaged in civil disobedience protesting "genocide in Gaza," participated in pro-Palestine demonstrations, and supports the Not on Our Dime Act.', summary = 'Participated in NYU Gaza Solidarity Encampment holding "PREGNANT MAMA FOR A FREE PALESTINE" sign. Engaged in civil disobedience protesting genocide in Gaza. Described Not on Our Dime Act as addressing "tax-exempt donations to illegal Israeli settlements." Won special election Feb 2026 to succeed Mayor Mamdani with DSA endorsement. Sources: https://socialists.nyc/press-releases/democratic-socialist-diana-moreno-wins-special-election-in-assembly-district-36-to-succeed-mayor-mamdani/ , https://jaco', updated_at = NOW();
