INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (100, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA member who explicitly calls Israeli actions "genocide" and "apartheid," supports BDS, co-sponsors Not on Our Dime Act, and calls for cutting all US military aid to Israel.', 'Self-described as "a vocal and consistent opponent of the Israeli genocide in Gaza and the system of apartheid that denies freedom for all Palestinians." Supports BDS and calls for cutting all US military aid to Israel. Co-sponsors Not on Our Dime Act. Endorsed by pro-Palestinian PAL PAC for Congress. Was arrested protesting after Oct 7. Sources: https://www.cityandstateny.com/politics/2026/03/pro-palestinian-pal-pac-endorses-claire-valdez-congress/412325/ , https://jacobin.com/2026/01/claire-va') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA member who explicitly calls Israeli actions "genocide" and "apartheid," supports BDS, co-sponsors Not on Our Dime Act, and calls for cutting all US military aid to Israel.', summary = 'Self-described as "a vocal and consistent opponent of the Israeli genocide in Gaza and the system of apartheid that denies freedom for all Palestinians." Supports BDS and calls for cutting all US military aid to Israel. Co-sponsors Not on Our Dime Act. Endorsed by pro-Palestinian PAL PAC for Congress. Was arrested protesting after Oct 7. Sources: https://www.cityandstateny.com/politics/2026/03/pro-palestinian-pal-pac-endorses-claire-valdez-congress/412325/ , https://jacobin.com/2026/01/claire-va', updated_at = NOW();
