INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (101, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Described as having "unwavering support of Israel," commended by Rabbinical Alliance for anti-antisemitism efforts, endorsed by Zioness Action Fund, and signed letter opposing legislation targeting Jewish charities with Israel connections.', 'Endorsed by Zioness Action Fund for Public Advocate (pro-Israel organization). Commended by Rabbinical Alliance of America for anti-antisemitism leadership. Signed joint letter opposing bill she characterized as "a ploy to demonize Jewish charities with connections to Israel." Called Gaza peace deal a "long-awaited glimmer of hope." Sources: https://zionessaction.org/2025-nyc-democratic-primary-endorsements/ , https://rabbinicalalliance.org/2024/08/19/raa-commends-assembly-member-jenifer-rajkuma') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Described as having "unwavering support of Israel," commended by Rabbinical Alliance for anti-antisemitism efforts, endorsed by Zioness Action Fund, and signed letter opposing legislation targeting Jewish charities with Israel connections.', summary = 'Endorsed by Zioness Action Fund for Public Advocate (pro-Israel organization). Commended by Rabbinical Alliance of America for anti-antisemitism leadership. Signed joint letter opposing bill she characterized as "a ploy to demonize Jewish charities with connections to Israel." Called Gaza peace deal a "long-awaited glimmer of hope." Sources: https://zionessaction.org/2025-nyc-democratic-primary-endorsements/ , https://rabbinicalalliance.org/2024/08/19/raa-commends-assembly-member-jenifer-rajkuma', updated_at = NOW();
