INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (104, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Among the most outspoken pro-Israel voices in the Assembly; famously tweeted "Palestine does not exist," lost committee seat over it, and represents a large Orthodox Jewish constituency in Brooklyn.', 'Tweeted "Palestine does not exist" in 2019, refused to apologize, was removed from City Council immigration committee. Endorsed by pro-Israel Solidarity PAC. Spoke at pro-Israel rallies calling Hamas attack "most heinous acts of barbarism." Criticized BDS movement. Sources: https://www.timesofisrael.com/nyc-councilman-who-tweeted-palestine-does-not-exist-loses-committee-seat/ , https://vinnews.com/2023/10/19/watch-local-frum-nyc-politicians-express-support-for-israel-at-recent-rally/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Among the most outspoken pro-Israel voices in the Assembly; famously tweeted "Palestine does not exist," lost committee seat over it, and represents a large Orthodox Jewish constituency in Brooklyn.', summary = 'Tweeted "Palestine does not exist" in 2019, refused to apologize, was removed from City Council immigration committee. Endorsed by pro-Israel Solidarity PAC. Spoke at pro-Israel rallies calling Hamas attack "most heinous acts of barbarism." Criticized BDS movement. Sources: https://www.timesofisrael.com/nyc-councilman-who-tweeted-palestine-does-not-exist-loses-committee-seat/ , https://vinnews.com/2023/10/19/watch-local-frum-nyc-politicians-express-support-for-israel-at-recent-rally/', updated_at = NOW();
