INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (105, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'As Brooklyn Democratic Party chair, issued strong condemnation of Hamas and statement of solidarity with Israel; spoke at "South Brooklyn Stands with Israel" rally; visited Israel and has consistent pro-Israel record.', 'Brooklyn Democratic Party statement under her leadership: "strongly condemns the heinous and unconscionable assault on Israel by Hamas." Spoke at "South Brooklyn Stands with Israel" rally in May 2024. Visited Israel in 2011. Sources: https://brooklyneagle.com/articles/2024/05/22/political-leadership-in-south-brooklyn-standing-with-israel/ , https://brooklyneagle.com/articles/2024/05/18/south-brooklyn-stands-for-israel-electeds-community-leaders-rally-for-release-of-hostages-held-by-hamas-this-su') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'As Brooklyn Democratic Party chair, issued strong condemnation of Hamas and statement of solidarity with Israel; spoke at "South Brooklyn Stands with Israel" rally; visited Israel and has consistent pro-Israel record.', summary = 'Brooklyn Democratic Party statement under her leadership: "strongly condemns the heinous and unconscionable assault on Israel by Hamas." Spoke at "South Brooklyn Stands with Israel" rally in May 2024. Visited Israel in 2011. Sources: https://brooklyneagle.com/articles/2024/05/22/political-leadership-in-south-brooklyn-standing-with-israel/ , https://brooklyneagle.com/articles/2024/05/18/south-brooklyn-stands-for-israel-electeds-community-leaders-rally-for-release-of-hostages-held-by-hamas-this-su', updated_at = NOW();
