INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (107, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Supports conditional ceasefire (once hostages released), believes there should be conditions on aid to Israel, refuses AIPAC money, but does not take strongly pro- or anti-Israel positions.', 'In JOLDC questionnaire (Jan 2024): "I support an immediate ceasefire once all the hostages are released." On conditioning aid: "my sense is there should be conditions to aid." On AIPAC: "Yes. I have never taken money from AIPAC." Sources: https://jimowles.org/news/candidate-answers-to-joldc-robert-carroll-for-ny-assembly-district-44-2024') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Supports conditional ceasefire (once hostages released), believes there should be conditions on aid to Israel, refuses AIPAC money, but does not take strongly pro- or anti-Israel positions.', summary = 'In JOLDC questionnaire (Jan 2024): "I support an immediate ceasefire once all the hostages are released." On conditioning aid: "my sense is there should be conditions to aid." On AIPAC: "Yes. I have never taken money from AIPAC." Sources: https://jimowles.org/news/candidate-answers-to-joldc-robert-carroll-for-ny-assembly-district-44-2024', updated_at = NOW();
