INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (112, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Self-described "proud Jewish-American, lifelong Zionist and stalwart advocate for Israel" who sponsored Oct 7 commemoration legislation and wears a yellow ribbon pin for hostages.', 'Identifies as "a proud Jewish-American, a lifelong-Zionist and a stalwart advocate for Israel." Sponsored bipartisan bill to enshrine October 7 as a day of commemoration in New York. Wears yellow ribbon pin for hostages. Sources: https://www.yahoo.com/news/ny-assembly-dems-accused-veiled-235242323.html , https://politicsny.com/2025/08/25/inside-government-with-politicsny-a-qa-with-assembly-member-lester-chang/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Self-described "proud Jewish-American, lifelong Zionist and stalwart advocate for Israel" who sponsored Oct 7 commemoration legislation and wears a yellow ribbon pin for hostages.', summary = 'Identifies as "a proud Jewish-American, a lifelong-Zionist and a stalwart advocate for Israel." Sponsored bipartisan bill to enshrine October 7 as a day of commemoration in New York. Wears yellow ribbon pin for hostages. Sources: https://www.yahoo.com/news/ny-assembly-dems-accused-veiled-235242323.html , https://politicsny.com/2025/08/25/inside-government-with-politicsny-a-qa-with-assembly-member-lester-chang/', updated_at = NOW();
