INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (113, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA-backed Assembly member, co-sponsor of the "Not on Our Dime" Act targeting Israeli settlement funding, early ceasefire advocate, and co-introduced legislation to help New Yorkers stranded in Israel/Gaza/West Bank.', 'Called for ceasefire on Oct 15, 2023, joining faith leaders for a vigil. Co-introduced the "Not on our dime!: Ending New York funding of Israeli settler violence act" (A6101) with Mamdani, Shrestha, Forrest, and Mitaynes. Co-sponsored legislation to help stranded New Yorkers in Israel, Gaza, and West Bank. Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ , https://www.nysenate.gov/legislation/bills/2025/A6101') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA-backed Assembly member, co-sponsor of the "Not on Our Dime" Act targeting Israeli settlement funding, early ceasefire advocate, and co-introduced legislation to help New Yorkers stranded in Israel/Gaza/West Bank.', summary = 'Called for ceasefire on Oct 15, 2023, joining faith leaders for a vigil. Co-introduced the "Not on our dime!: Ending New York funding of Israeli settler violence act" (A6101) with Mamdani, Shrestha, Forrest, and Mitaynes. Co-sponsored legislation to help stranded New Yorkers in Israel, Gaza, and West Bank. Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ , https://www.nysenate.gov/legislation/bills/2025/A6101', updated_at = NOW();
