INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (114, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA member arrested at pro-ceasefire protests, co-sponsor of "Not on Our Dime" Act, participated in statements referencing "genocide in Gaza" and "Israeli apartheid," and has been a consistent vocal critic of Israel.', 'Arrested at pro-ceasefire protest outside Schumer''s apartment Oct 13, 2023. Arrested again at Grand Army Plaza protest Aug 2025. Co-sponsor of Not on Our Dime Act (A6101). Participated in DSA statements calling for end to "genocide in Gaza and Israeli apartheid." Sources: https://socialists.nyc/press-releases/new-yorkers-demand-ceasefire-in-gaza/ , https://peoplesdispatch.org/2025/08/04/pressure-mounts-on-us-politicians-as-democratic-party-voter-base-pushes-to-end-aid-to-israel/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA member arrested at pro-ceasefire protests, co-sponsor of "Not on Our Dime" Act, participated in statements referencing "genocide in Gaza" and "Israeli apartheid," and has been a consistent vocal critic of Israel.', summary = 'Arrested at pro-ceasefire protest outside Schumer''s apartment Oct 13, 2023. Arrested again at Grand Army Plaza protest Aug 2025. Co-sponsor of Not on Our Dime Act (A6101). Participated in DSA statements calling for end to "genocide in Gaza and Israeli apartheid." Sources: https://socialists.nyc/press-releases/new-yorkers-demand-ceasefire-in-gaza/ , https://peoplesdispatch.org/2025/08/04/pressure-mounts-on-us-politicians-as-democratic-party-voter-base-pushes-to-end-aid-to-israel/', updated_at = NOW();
