INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (115, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Opposes BDS but criticizes Israel''s military conduct as causing disproportionate civilian casualties; supports conditioning aid but acknowledges limited state-level role on foreign policy.', 'In 2022 congressional forum, opposed BDS. In 2024 JOLDC questionnaire, stated "Israel has to conduct its operations in a manner consistent with international law and its incessant bombing has caused way too many deaths of noncombatants, a disproportionate number of whom were children." Supports conditions on aid. Would not accept AIPAC money. Sources: https://jimowles.org/news/candidate-answers-to-joldc-jo-anne-simon-for-ny-assembly-district-52-2024 , https://forward.com/news/512251/in-brooklyn-') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Opposes BDS but criticizes Israel''s military conduct as causing disproportionate civilian casualties; supports conditioning aid but acknowledges limited state-level role on foreign policy.', summary = 'In 2022 congressional forum, opposed BDS. In 2024 JOLDC questionnaire, stated "Israel has to conduct its operations in a manner consistent with international law and its incessant bombing has caused way too many deaths of noncombatants, a disproportionate number of whom were children." Supports conditions on aid. Would not accept AIPAC money. Sources: https://jimowles.org/news/candidate-answers-to-joldc-jo-anne-simon-for-ny-assembly-district-52-2024 , https://forward.com/news/512251/in-brooklyn-', updated_at = NOW();
