INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (117, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Supported by pro-Israel networks; campaign materials attacked opponents for poor "voting records on Israel"; won against DSA-backed candidates with support from NYSN-affiliated figures.', 'Campaign handout attacked political opponent for having "the worst voting record on Israel in the New York congressional delegation." Won race against DSA-endorsed candidates with support from figures tied to NYSN (New York Solidarity Network), a pro-Israel group. Sources: https://jewishcurrents.org/republicans-are-helping-new-york-democrats-target-the-lefts-israel-criticism') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Supported by pro-Israel networks; campaign materials attacked opponents for poor "voting records on Israel"; won against DSA-backed candidates with support from NYSN-affiliated figures.', summary = 'Campaign handout attacked political opponent for having "the worst voting record on Israel in the New York congressional delegation." Won race against DSA-endorsed candidates with support from figures tied to NYSN (New York Solidarity Network), a pro-Israel group. Sources: https://jewishcurrents.org/republicans-are-helping-new-york-democrats-target-the-lefts-israel-criticism', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (119, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Position is deliberately murky; received significant pro-Israel PAC funding (~$41K from Solidarity PAC) but has reportedly called for ceasefire (disputed); did not sign "Not on Our Dime" legislation.', 'Received nearly $41,000 from pro-Israel Solidarity PAC (about half her fundraising). Public Advocate Jumaane Williams claimed she called for ceasefire, but her opponent disputed this. Did not sign "Not on Our Dime" legislation. Condemned Hamas attack. Faced DSA primary challenge over Israel stance. Sources: https://indypendent.org/2024/06/zinermans-palestine-position-remains-murky-as-special-interest-money-pours-into-central-brooklyn-assembly-race/ , https://forward.com/fast-forward/627460/new-y') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Position is deliberately murky; received significant pro-Israel PAC funding (~$41K from Solidarity PAC) but has reportedly called for ceasefire (disputed); did not sign "Not on Our Dime" legislation.', summary = 'Received nearly $41,000 from pro-Israel Solidarity PAC (about half her fundraising). Public Advocate Jumaane Williams claimed she called for ceasefire, but her opponent disputed this. Did not sign "Not on Our Dime" legislation. Condemned Hamas attack. Faced DSA primary challenge over Israel stance. Sources: https://indypendent.org/2024/06/zinermans-palestine-position-remains-murky-as-special-interest-money-pours-into-central-brooklyn-assembly-race/ , https://forward.com/fast-forward/627460/new-y', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (120, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA member who used "apartheid" language about Israel, shared map erasing Israel, co-sponsored "Not on Our Dime" Act, called for unconditional ceasefire, and has been one of the most outspoken anti-Israel voices in the Assembly.', 'Shared map in 2021 labeling all of Israel as "Palestine" with #FreePalestine (later deleted). Stated "the reality on the ground is apartheid" and "continued occupation and apartheid and the denial of Palestinian humanity." Co-introduced Not on Our Dime Act (A6101). Called for ceasefire at Oct 2023 demonstration. Sources: https://www.washingtonexaminer.com/news/58453/new-york-state-legislator-shares-image-erasing-israel-from-the-map/ , https://www.nysenate.gov/legislation/bills/2025/A6101') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA member who used "apartheid" language about Israel, shared map erasing Israel, co-sponsored "Not on Our Dime" Act, called for unconditional ceasefire, and has been one of the most outspoken anti-Israel voices in the Assembly.', summary = 'Shared map in 2021 labeling all of Israel as "Palestine" with #FreePalestine (later deleted). Stated "the reality on the ground is apartheid" and "continued occupation and apartheid and the denial of Palestinian humanity." Co-introduced Not on Our Dime Act (A6101). Called for ceasefire at Oct 2023 demonstration. Sources: https://www.washingtonexaminer.com/news/58453/new-york-state-legislator-shares-image-erasing-israel-from-the-map/ , https://www.nysenate.gov/legislation/bills/2025/A6101', updated_at = NOW();
