INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (123, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Backed by pro-Israel-aligned groups against DSA candidates but no explicit personal statements on Israel/Palestine found; Israel was not a prominent campaign issue.', 'Won race against DSA-endorsed candidate with support from figures tied to NYSN (New York Statewide Network), a pro-Israel group. However, no specific personal statements on Israel/Palestine were found. Sources: https://jewishcurrents.org/republicans-are-helping-new-york-democrats-target-the-lefts-israel-criticism , https://forward.com/fast-forward/627460/new-york-assembly-dsa-pro-palestinian-israel/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Backed by pro-Israel-aligned groups against DSA candidates but no explicit personal statements on Israel/Palestine found; Israel was not a prominent campaign issue.', summary = 'Won race against DSA-endorsed candidate with support from figures tied to NYSN (New York Statewide Network), a pro-Israel group. However, no specific personal statements on Israel/Palestine were found. Sources: https://jewishcurrents.org/republicans-are-helping-new-york-democrats-target-the-lefts-israel-criticism , https://forward.com/fast-forward/627460/new-york-assembly-dsa-pro-palestinian-israel/', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (124, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'First Muslim Assembly member who traveled to Israel with JCRC delegation to learn about the conflict, defended the trip against critics, and emphasized interfaith dialogue without taking a strongly pro- or anti-Israel position.', 'Traveled to Israel with JCRC-sponsored Assembly delegation in 2020, visiting Bethlehem, Western Wall, and border areas. Islamic Leadership Council of NY condemned the trip. Fall responded he "will not and should not have to justify or apologize for my trip" and emphasized interfaith unity against Islamophobia and antisemitism. Sources: https://www.middleeasteye.net/news/politician-charles-fall-slammed-israel-visit , https://assembly.state.ny.us/mem/Charles-D-Fall/story/91112') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'First Muslim Assembly member who traveled to Israel with JCRC delegation to learn about the conflict, defended the trip against critics, and emphasized interfaith dialogue without taking a strongly pro- or anti-Israel position.', summary = 'Traveled to Israel with JCRC-sponsored Assembly delegation in 2020, visiting Bethlehem, Western Wall, and border areas. Islamic Leadership Council of NY condemned the trip. Fall responded he "will not and should not have to justify or apologize for my trip" and emphasized interfaith unity against Islamophobia and antisemitism. Sources: https://www.middleeasteye.net/news/politician-charles-fall-slammed-israel-visit , https://assembly.state.ny.us/mem/Charles-D-Fall/story/91112', updated_at = NOW();
