INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (126, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Republican Assembly member from Staten Island who was part of a statement calling the Oct 7 attack on Israel "a war crime" and expressing solidarity with Israel.', 'Was part of statement calling the attack on Israeli people "a war crime." Appeared on "New York Legislators Stand with Israel" document (Oct 2023). Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Republican Assembly member from Staten Island who was part of a statement calling the Oct 7 attack on Israel "a war crime" and expressing solidarity with Israel.', summary = 'Was part of statement calling the attack on Israeli people "a war crime." Appeared on "New York Legislators Stand with Israel" document (Oct 2023). Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', updated_at = NOW();
