INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (128, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Fully supports Israel''s right to defend itself and condemns Oct 7 attacks, while also criticizing far-right Israeli government and calling for humanitarian aid to Palestinian civilians and a two-state solution.', 'In 2024 JOLDC questionnaire: "I fully support Israel''s right to defend itself and fully condemn the terrorist attacks on October 7th." Criticized "reckless actions of the far right government in Israel." Supports two-state solution, bringing hostages home, and humanitarian aid. Voted against censure of Rep. Rashida Tlaib. Sources: https://jimowles.org/news/candidate-answers-to-joldc-grace-lee-for-ny-assembly-district-65-2024') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Fully supports Israel''s right to defend itself and condemns Oct 7 attacks, while also criticizing far-right Israeli government and calling for humanitarian aid to Palestinian civilians and a two-state solution.', summary = 'In 2024 JOLDC questionnaire: "I fully support Israel''s right to defend itself and fully condemn the terrorist attacks on October 7th." Criticized "reckless actions of the far right government in Israel." Supports two-state solution, bringing hostages home, and humanitarian aid. Voted against censure of Rep. Rashida Tlaib. Sources: https://jimowles.org/news/candidate-answers-to-joldc-grace-lee-for-ny-assembly-district-65-2024', updated_at = NOW();
