INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (129, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Long-serving Assembly member who strongly supports Israel''s right to exist and has opposed BDS, though she blocked an anti-boycott bill in committee on academic freedom grounds.', 'Stated she supports "very, very strongly" Israel''s right to exist (2015). Opposed BDS movement. As Higher Education Committee chair, pulled an anti-boycott bill from agenda but said it would be reworked - balancing opposition to BDS with academic freedom concerns. Sources: https://www.cityandstateny.com/politics/2019/04/where-new-york-democrats-stand-on-israel/177469/ , http://pacbi.org/pacbi140812/?p=2363') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Long-serving Assembly member who strongly supports Israel''s right to exist and has opposed BDS, though she blocked an anti-boycott bill in committee on academic freedom grounds.', summary = 'Stated she supports "very, very strongly" Israel''s right to exist (2015). Opposed BDS movement. As Higher Education Committee chair, pulled an anti-boycott bill from agenda but said it would be reworked - balancing opposition to BDS with academic freedom concerns. Sources: https://www.cityandstateny.com/politics/2019/04/where-new-york-democrats-stand-on-israel/177469/ , http://pacbi.org/pacbi140812/?p=2363', updated_at = NOW();
